// Regenerates `hybrid_vectors.json` — the `hpke-hybrid-v1` interop goldens the
// Python `hybrid` tests read.
//
// The vectors are produced by the TypeScript stack (`rine-core`), never by
// Python, which is the whole point: a Python round-trip proves Python agrees
// with itself, and this proves the two stacks agree with each other.
//
// Run from rine-sdk/, the same way `generate_vectors.mjs` is run:
//
//   npx tsx tests/fixtures/generate_hybrid_vectors.mjs > tests/fixtures/hybrid_vectors.json
//
// Only regenerate when the wire format deliberately changes. A vector that
// stops decrypting is the alarm this file exists to raise.

import * as fs from "node:fs";
import * as os from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

// rine-core is a sibling directory in the worktree. Dynamic imports resolve the
// .ts sources through tsx, so no build step and no stale dist.
const CORE_CRYPTO = join(
	dirname(fileURLToPath(import.meta.url)),
	"..",
	"..",
	"..",
	"rine-core",
	"src",
	"crypto",
);

const { generateAgentKeys, saveAgentKeys } = await import(CORE_CRYPTO + "/keys.ts");
const { encryptMessage } = await import(CORE_CRYPTO + "/message.ts");
const { sealHybrid } = await import(CORE_CRYPTO + "/hybrid.ts");

const b64 = (u8) => Buffer.from(u8).toString("base64url");

const senderId = "11111111-1111-4111-8111-111111111111";
const recipientId = "22222222-2222-4222-8222-222222222222";
const configDir = fs.mkdtempSync(join(os.tmpdir(), "rine-hybrid-vectors-"));

const senderKeys = generateAgentKeys();
const recipientKeys = generateAgentKeys();
saveAgentKeys(configDir, senderId, senderKeys);
saveAgentKeys(configDir, recipientId, recipientKeys);

const payload = { type: "rine.v1.text", text: "post-quantum hello from TypeScript" };

// The negotiated path: the recipient publishes an ML-KEM key, so rine-core
// seals `hpke-hybrid-v1` without being asked to.
const negotiated = await encryptMessage(
	configDir,
	senderId,
	recipientKeys.encryption.publicKey,
	payload,
	recipientKeys.pqEncryption.publicKey,
);

// A payload with additional authenticated data, so the Python side is pinned on
// AAD binding rather than only on the happy path.
const aad = new TextEncoder().encode("rine.v1.aad-probe");
const withAad = await sealHybrid(
	recipientKeys.encryption.publicKey,
	recipientKeys.pqEncryption.publicKey,
	new TextEncoder().encode("aad-bound plaintext"),
	aad,
);

fs.rmSync(configDir, { recursive: true, force: true });

console.log(
	JSON.stringify(
		{
			_comment:
				"Generated by tests/fixtures/generate_hybrid_vectors.mjs from rine-core. Do not hand-edit.",
			sender_agent_id: senderId,
			recipient_agent_id: recipientId,
			sender_signing_private_key: b64(senderKeys.signing.privateKey),
			sender_signing_public_key: b64(senderKeys.signing.publicKey),
			recipient_signing_private_key: b64(recipientKeys.signing.privateKey),
			recipient_encryption_private_key: b64(recipientKeys.encryption.privateKey),
			recipient_encryption_public_key: b64(recipientKeys.encryption.publicKey),
			recipient_pq_private_key: b64(recipientKeys.pqEncryption.privateKey),
			recipient_pq_public_key: b64(recipientKeys.pqEncryption.publicKey),
			sender_encryption_private_key: b64(senderKeys.encryption.privateKey),
			sender_pq_private_key: b64(senderKeys.pqEncryption.privateKey),
			plaintext: JSON.stringify(payload),
			encryption_version: negotiated.encryption_version,
			sender_signing_kid: negotiated.sender_signing_kid,
			encrypted_payload: negotiated.encrypted_payload,
			self_encrypted_payload: negotiated.self_encrypted_payload,
			aad: Buffer.from(aad).toString("base64url"),
			aad_plaintext: "aad-bound plaintext",
			aad_payload: b64(withAad),
		},
		null,
		2,
	),
);
